interface RangeOptions {
  start: number;
  end: number;
  step?: number;
  inclusive?: boolean;
}

// Creates an iterable range of numbers.
// Default step is 1 (or -1 if end < start).
// Default inclusive is TRUE (unlike Python's range which is exclusive).
// If step direction doesn't match start->end direction, return empty.
// Step must not be 0 (throw Error).
// Must implement Symbol.iterator protocol.

