const STANDARD_94 = Array.from({length: 94}, (_, i) => String.fromCharCode(33 + i)).join('');
const REVERSED_94 = STANDARD_94.split('').reverse().join('');

function bytesToBigInt(buf: Buffer): bigint {
  let n = 0n;
  for (const b of buf) {
    n = (n << 8n) | BigInt(b);
