      case 'replace':
        return target;
      case 'append':
        return source.concat(target);
      case 'prepend':
        return target.concat(source);
      case 'unique': {
        const result = [...source];
        for (const item of target) {
          if (!source.includes(item)) {
            result.push(item);
          }
        }
        return result;
      }
      default:
        return target;
    }
  }

  // Now handle objects (not null, not arrays)
  if (target !== null && typeof target === 'object') {
    if (source === null || typeof source !== 'object' || Array.isArray(source)) {
      return target; // target overwrites non-object source
    }
    if (options.depth === 0) {
      return target; // shallow replace when max depth reached
    }
    const merged = { ...source };
    for (const key in target) {
      if (Object.prototype.hasOwnProperty.call(target, key)) {
        if (Object.prototype.hasOwnProperty.call(source, key)) {
          merged[key] = mergeConfig(source[key], target[key], {
            arrayStrategy: options.arrayStrategy,
            depth: options.depth - 1,
          });
        } else {
          merged[key] = target[key];
        }
      }
    }
    return merged;
  }

  // Primitive target overwrites source
  return target;
}

